162:         Error(baton.get());
163:         stmt->Finalize_();
164:     }
165:     else {
166:         stmt->prepared = true;
167:         if (!baton->callback.IsEmpty() && baton->callback.Value().IsFunction()) {
168:             Napi::Function cb = baton->callback.Value();
169:             Napi::Value argv[] = { env.Null() };
170:             TRY_CATCH_CALL(stmt->Value(), cb, 1, argv);
171:         }
172:     }
173: 
174:     STATEMENT_END();
175: }
176: 
177: template <class T> Values::Field*
178:                    Statement::BindParameter(const Napi::Value source, T pos) {
179:     if (source.IsString()) {
180:         std::string val = source.As<Napi::String>().Utf8Value();
181:         return new Values::Text(pos, val.length(), val.c_str());
182:     }
183:     else if (OtherInstanceOf(source.As<Object>(), "RegExp")) {
184:         std::string val = source.ToString().Utf8Value();
185:         return new Values::Text(pos, val.length(), val.c_str());
186:     }
187:     else if (source.IsNumber()) {
188:         if (OtherIsInt(source.As<Napi::Number>())) {
189:             return new Values::Integer(pos, source.As<Napi::Number>().Int32Value());
190:         } else {
191:             return new Values::Float(pos, source.As<Napi::Number>().DoubleValue());
192:         }
193:     }
194:     else if (source.IsBoolean()) {
195:         return new Values::Integer(pos, source.As<Napi::Boolean>().Value() ? 1 : 0);
196:     }
197:     else if (source.IsNull()) {
198:         return new Values::Null(pos);
199:     }
200:     else if (source.IsBuffer()) {
201:         Napi::Buffer<char> buffer = source.As<Napi::Buffer<char>>();
202:         return new Values::Blob(pos, buffer.Length(), buffer.Data());
203:     }
204:     else if (OtherInstanceOf(source.As<Object>(), "Date")) {
205:         return new Values::Float(pos, source.ToNumber().DoubleValue());
206:     }
207:     else if (source.IsObject()) {
208:         std::string val = source.ToString().Utf8Value();
209:         return new Values::Text(pos, val.length(), val.c_str());
210:     }
211:     else {
212:         return NULL;
213:     }
214: }
