216: template <class T> T* Statement::Bind(const Napi::CallbackInfo& info, int start, int last) {
217:     Napi::Env env = info.Env();
218:     Napi::HandleScope scope(env);
219: 
220:     if (last < 0) last = info.Length();
221:     Napi::Function callback;
222:     if (last > start && info[last - 1].IsFunction()) {
223:         callback = info[last - 1].As<Napi::Function>();
224:         last--;
225:     }
226: 
227:     T* baton = new T(this, callback);
228: 
229:     if (start < last) {
230:         if (info[start].IsArray()) {
231:             Napi::Array array = info[start].As<Napi::Array>();
232:             int length = array.Length();
233:             // Note: bind parameters start with 1.
234:             for (int i = 0, pos = 1; i < length; i++, pos++) {
235:                 baton->parameters.push_back(BindParameter((array).Get(i), pos));
236:             }
237:         }
238:         else if (!info[start].IsObject() || OtherInstanceOf(info[start].As<Object>(), "RegExp") || OtherInstanceOf(info[start].As<Object>(), "Date") || info[start].IsBuffer()) {
239:             // Parameters directly in array.
240:             // Note: bind parameters start with 1.
241:             for (int i = start, pos = 1; i < last; i++, pos++) {
242:                 baton->parameters.push_back(BindParameter(info[i], pos));
243:             }
244:         }
245:         else if (info[start].IsObject()) {
246:             Napi::Object object = info[start].As<Napi::Object>();
247:             Napi::Array array = object.GetPropertyNames();
248:             int length = array.Length();
249:             for (int i = 0; i < length; i++) {
250:                 Napi::Value name = (array).Get(i);
251:                 Napi::Number num = name.ToNumber();
252: 
253:                 if (num.Int32Value() == num.DoubleValue()) {
254:                     baton->parameters.push_back(
255:                         BindParameter((object).Get(name), num.Int32Value()));
256:                 }
257:                 else {
258:                     baton->parameters.push_back(BindParameter((object).Get(name),
259:                         name.As<Napi::String>().Utf8Value().c_str()));
260:                 }
261:             }
262:         }
263:         else {
264:             return NULL;
265:         }
266:     }
267: 
268:     return baton;
269: }
