399: void Statement::Work_Get(napi_env e, void* data) {
400:     STATEMENT_INIT(RowBaton);
401: 
402:     if (stmt->status != SQLITE_DONE || baton->parameters.size()) {
403:         STATEMENT_MUTEX(mtx);
404:         sqlite3_mutex_enter(mtx);
405: 
406:         if (stmt->Bind(baton->parameters)) {
407:             stmt->status = sqlite3_step(stmt->_handle);
408: 
409:             if (!(stmt->status == SQLITE_ROW || stmt->status == SQLITE_DONE)) {
410:                 stmt->message = std::string(sqlite3_errmsg(stmt->db->_handle));
411:             }
412:         }
413: 
414:         sqlite3_mutex_leave(mtx);
415: 
416:         if (stmt->status == SQLITE_ROW) {
417:             // Acquire one result row before returning.
418:             GetRow(&baton->row, stmt->_handle);
419:         }
420:     }
