631: void Statement::Work_BeginEach(Baton* baton) {
632:     // Only create the Async object when we're actually going into
633:     // the event loop. This prevents dangling events.
634:     EachBaton* each_baton = static_cast<EachBaton*>(baton);
635:     each_baton->async = new Async(each_baton->stmt, reinterpret_cast<uv_async_cb>(AsyncEach));
636:     each_baton->async->item_cb.Reset(each_baton->callback.Value(), 1);
637:     each_baton->async->completed_cb.Reset(each_baton->completed.Value(), 1);
638: 
639:     STATEMENT_BEGIN(Each);
640: }
641: 
642: void Statement::Work_Each(napi_env e, void* data) {
643:     STATEMENT_INIT(EachBaton);
644: 
645:     Async* async = baton->async;
646: 
647:     STATEMENT_MUTEX(mtx);
648: 
649:     int retrieved = 0;
650: 
651:     // Make sure that we also reset when there are no parameters.
652:     if (!baton->parameters.size()) {
653:         sqlite3_reset(stmt->_handle);
654:     }
655: 
656:     if (stmt->Bind(baton->parameters)) {
657:         while (true) {
658:             sqlite3_mutex_enter(mtx);
659:             stmt->status = sqlite3_step(stmt->_handle);
660:             if (stmt->status == SQLITE_ROW) {
661:                 sqlite3_mutex_leave(mtx);
662:                 Row* row = new Row();
663:                 GetRow(row, stmt->_handle);
664:                 NODE_SQLITE3_MUTEX_LOCK(&async->mutex)
665:                 async->data.push_back(row);
666:                 retrieved++;
667:                 NODE_SQLITE3_MUTEX_UNLOCK(&async->mutex)
668: 
669:                 uv_async_send(&async->watcher);
670:             }
671:             else {
672:                 if (stmt->status != SQLITE_DONE) {
673:                     stmt->message = std::string(sqlite3_errmsg(stmt->db->_handle));
674:                 }
675:                 sqlite3_mutex_leave(mtx);
676:                 break;
677:             }
678:         }
679:     }
680: 
681:     async->completed = true;
682:     uv_async_send(&async->watcher);
683: }
