685: void Statement::CloseCallback(uv_handle_t* handle) {
686:     assert(handle != NULL);
687:     assert(handle->data != NULL);
688:     Async* async = static_cast<Async*>(handle->data);
689:     delete async;
690: }
691: 
692: void Statement::AsyncEach(uv_async_t* handle) {
693:     Async* async = static_cast<Async*>(handle->data);
694: 
695:     Napi::Env env = async->stmt->Env();
696:     Napi::HandleScope scope(env);
697: 
698:     while (true) {
699:         // Get the contents out of the data cache for us to process in the JS callback.
700:         Rows rows;
701:         NODE_SQLITE3_MUTEX_LOCK(&async->mutex)
702:         rows.swap(async->data);
703:         NODE_SQLITE3_MUTEX_UNLOCK(&async->mutex)
704: 
705:         if (rows.empty()) {
706:             break;
707:         }
708: 
709:         Napi::Function cb = async->item_cb.Value();
710:         if (!cb.IsUndefined() && cb.IsFunction()) {
711:             Napi::Value argv[2];
712:             argv[0] = env.Null();
713: 
714:             Rows::const_iterator it = rows.begin();
715:             Rows::const_iterator end = rows.end();
716:             for (int i = 0; it < end; ++it, i++) {
717:                 std::unique_ptr<Row> row(*it);
718:                 argv[1] = RowToJS(env,row.get());
719:                 async->retrieved++;
720:                 TRY_CATCH_CALL(async->stmt->Value(), cb, 2, argv);
721:             }
722:         }
723:     }
724: 
725:     Napi::Function cb = async->completed_cb.Value();
726:     if (async->completed) {
727:         if (!cb.IsEmpty() &&
728:                 cb.IsFunction()) {
729:             Napi::Value argv[] = {
730:                 env.Null(),
731:                 Napi::Number::New(env, async->retrieved)
732:             };
733:             TRY_CATCH_CALL(async->stmt->Value(), cb, 2, argv);
734:         }
735:         uv_close(reinterpret_cast<uv_handle_t*>(handle), CloseCallback);
736:     }
737: }
