793: Napi::Value Statement::RowToJS(Napi::Env env, Row* row) {
794:     Napi::EscapableHandleScope scope(env);
795: 
796:     Napi::Object result = Napi::Object::New(env);
797: 
798:     Row::const_iterator it = row->begin();
799:     Row::const_iterator end = row->end();
800:     for (int i = 0; it < end; ++it, i++) {
801:         Values::Field* field = *it;
802: 
803:         Napi::Value value;
804: 
